\(\begin{aligned}
& \sqrt{x+1}-|\sqrt{x-1}|=\sqrt{4 x-1} \\
& \Rightarrow \sqrt{x+1}-\sqrt{4 x-1}=|\sqrt{x-1}|
\end{aligned}\)
Squaring on both sides
\(\begin{array}{ll}
\Rightarrow & x+1+4 x-1-2 \sqrt{(x+1)(4 x-1)}=x-1 \\
\Rightarrow & 5 x-2 \sqrt{(x+1)(4 x-1)}=x-1 \\
\Rightarrow & 4 x+1=2 \sqrt{(x+1)(4 x-1)}
\end{array}\)
Squaring on both sides
\(\begin{array}{lll}
\Rightarrow & 16 x^2+1+8 x=4\left(4 x^2+3 x-1\right) \\
\Rightarrow & 16 x^2+8 x+1=16 x^2+12 x-4 \\
\Rightarrow & 4 x=5 \Rightarrow x=\frac{5}{4}
\end{array}\)

\(\begin{aligned}
& \tanh (x)=\frac{1}{3}, \tanh (3 x)=? \\
& \Rightarrow \quad \frac{e^x-e^{-x}}{e^x+e^{-x}}=\frac{1}{3} \Rightarrow 2 e^x=4 e^{-x} \Rightarrow\left(e^{2 x}=2\right) \\
& \text {and } \tanh (3 x)=\frac{e^{3 x}-e^{-3 x}}{e^{3 x}+e^{-3 x}}=\frac{\left(e^{2 x}\right)^3-1}{\left(e^{2 x}\right)^3+1}=\frac{8-1}{8+1}=\frac{7}{9}
\end{aligned}\)

Given, \(l_1=560 \mathrm{~cm}, R=10 \Omega\),
\(\Rightarrow \quad \begin{aligned}
& l_2=l_1-60 \\
& l_2=560-60=500 \mathrm{~cm}
\end{aligned}\)
\(\therefore\) Internal resistance of cell is given by
\(\begin{aligned}
& r=\left(\frac{l_1-l_2}{l_2}\right) R=\left(\frac{560-500}{500}\right) 10 \\
& =\frac{60}{500} \times 10=\frac{6}{5}=1.2 \Omega
\end{aligned}\)

